// finition des portes (option finish) : inox (défaut), blanc ou noir
const fridgeFinish = (c) => ({ white: "fwhite", blanc: "fwhite", black: "fblack", noir: "fblack" }[String(c?.finish || "").toLowerCase()] || "");
SVG.fridge = (c) => {
  const f = fridgeFinish(c), body = FRIDGE[fridgeStyle(c)](!!(c && c.flex_temperature));
  return `${FRIDGE_DEFS}${f ? body.replace(/url\(#ID-inox\)/g, `url(#ID-${f})`) : body}${fridgeMist}`;
};

/* Réfrigérateur et congélateur à tiroirs vus de côté (option view: side), tous les styles : voir side_kit.js (sideFromFront). */
const FRIDGE_SVG_PREV = SVG.fridge;
const fridgeRect = (st) => ({ four_door: [16, 4, 104, 130], french: [16, 4, 104, 130], american: [12, 4, 108, 130] }[st] || [26, 4, 94, 130]);
SVG.fridge = (c) => {
  if (!(c && c.view === "side")) return FRIDGE_SVG_PREV(c);
  const st = fridgeStyle(c), f = fridgeFinish(c);
  let body = sideFromFront(FRIDGE[st](!!c.flex_temperature), fridgeRect(st), { sw: .45 });
  if (f) body = body.replace(/url\(#ID-inox\)/g, `url(#ID-${f})`);
  return `${FRIDGE_DEFS}${body}${fridgeMist}`;
};
const DRAWER_FREEZER_PREV = SVG.drawer_freezer;
SVG.drawer_freezer = (c) => (c && c.view === "side" ? (() => { const s = DRAWER_FREEZER_PREV(c), d = s.match(/<defs>[\s\S]*?<\/defs>/)[0]; return d + sideFromFront(s.replace(d, ""), [26, 4, 94, 130], { sw: .45, sideFill: "#cfd5db", sideEdge: "#bfc6ce", body: /<rect[^>]*fill="#9aa2ab"[^>]*\/>/ }); })() : DRAWER_FREEZER_PREV(c));

SVG.garland = () => {
  // deux rangées de festons sous une poutre de terrasse, trois globes par feston
  const sw = [[6, 24, 60, 26], [60, 24, 114, 26], [6, 62, 42, 16], [42, 62, 78, 16], [78, 62, 114, 16]], P = [];
  sw.forEach(([x0, y, x1, h]) => { for (const t of [.25, .5, .75]) P.push([x0 + (x1 - x0) * t, y + 4 * h * t * (1 - t)]); });
  const cord = sw.map(([x0, y, x1, h]) => `M${x0} ${y} Q${(x0 + x1) / 2} ${y + 2 * h} ${x1} ${y}`).join("");
  return `
<defs>${DEFS}<radialGradient id="ID-glh"><stop offset="0" stop-color="#fff" stop-opacity=".9"/><stop offset=".35" stop-color="#fff" stop-opacity=".35"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></radialGradient></defs>
<rect class="gl-sky" width="120" height="140"/>
<rect x="0" y="18" width="120" height="7" fill="#8a6239"/><rect x="0" y="18" width="120" height="2" fill="#a77a4b"/>
<rect x="2" y="25" width="6" height="115" fill="#7a5532"/><rect x="112" y="25" width="6" height="115" fill="#7a5532"/>
<path class="gl-hedge" d="M8 118 q8-10 16 0 q8-12 18 0 q9-10 18 0 q9-12 18 0 q8-10 16 0 q6-8 10 0 v22 h-96z"/>
<rect x="0" y="128" width="120" height="12" fill="#b9a68a"/>
<path d="${cord}" stroke="#2b3036" stroke-width="1.1" fill="none"/>
${P.map(([x, y], i) => `<g class="gl-bulb" style="--d:${(-i * .3).toFixed(1)}s">
  <circle class="gl-h" cx="${x.toFixed(1)}" cy="${(y + 8).toFixed(1)}" r="8"/>
  <rect x="${(x - 1.8).toFixed(1)}" y="${y.toFixed(1)}" width="3.6" height="3" rx=".6" fill="#2b3036"/>
  <circle class="gl-b" cx="${x.toFixed(1)}" cy="${(y + 8).toFixed(1)}" r="5"/>
  <circle class="gl-g" cx="${x.toFixed(1)}" cy="${(y + 8).toFixed(1)}" r="5" fill="url(#ID-glh)"/>
</g>`).join("")}`;
};

/* Carte générique : l'utilisateur fournit sa propre image (option `image`) */
SVG.generic = (c = {}) => {
  // `images` (liste conditionnelle) : on part de la première ; la carte choisit ensuite selon l'état
  const list = Array.isArray(c && c.images) ? c.images.filter((i) => i && i.image) : [];
  const base = String((c && c.image) || (list[0] && list[0].image) || "").trim();
  // image_on / image_off : deux images distinctes selon que l'appareil fonctionne ou non (l'une des deux peut retomber sur `image`)
  const iOn = String((c && c.image_on) || "").trim(), iOff = String((c && c.image_off) || "").trim(), pair = !!(iOn || iOff);
  const src = pair ? iOff || base || iOn : base;
  const im = (cls, href) => `<image class="${cls}" href="${esc(href)}" x="4" y="6" width="112" height="124" preserveAspectRatio="xMidYMid meet"/>`;
  // anneau lumineux (option ring_light) : position et taille réglables, couleur / luminosité suivies de la lumière
  const rx = Number.isFinite(Number(c && c.ring_x)) && c.ring_x !== "" ? Number(c.ring_x) : 50, ry = Number.isFinite(Number(c && c.ring_y)) && c.ring_y !== "" ? Number(c.ring_y) : 46,
    rs = Number.isFinite(Number(c && c.ring_size)) && c.ring_size !== "" ? Number(c.ring_size) : 60, rr = (Math.max(5, Math.min(150, rs)) / 100) * 56, cxr = (rx / 100) * 120, cyr = (ry / 100) * 140;
  const ringOnly = c && c.ring_style === "ring";
  const ringG = c && c.ring_light ? (below) => (below
    ? `<g class="gn-ringg"><radialGradient id="ID-gnr" cx=".5" cy=".5" r=".5"><stop offset="0" stop-color="var(--rc,#fff)" stop-opacity=".9"/><stop offset="1" stop-color="var(--rc,#fff)" stop-opacity="0"/></radialGradient>${ringOnly ? "" : `<circle class="gn-halo" cx="${cxr.toFixed(1)}" cy="${cyr.toFixed(1)}" r="${(rr * 1.25).toFixed(1)}" fill="url(#ID-gnr)"/>`}</g>`
    : `<g class="gn-ringg gn-ringt">${ringOnly ? `<circle class="gn-ring" cx="${cxr.toFixed(1)}" cy="${cyr.toFixed(1)}" r="${rr.toFixed(1)}" fill="none"/>` : ""}</g>`) : () => "";
  const art = pair || src
    ? (pair ? im("gn-p gn-off", src) + im("gn-p gn-on", iOn || base || iOff) : im("gn-img", src))
    // pas d'image : pictogramme de prise pour inviter à renseigner `image`
    : `<g class="gn-img gn-empty">
  <rect x="14" y="22" width="92" height="92" rx="16" fill="none" stroke="#8d959f" stroke-width="2" stroke-dasharray="5 5"/>
  <rect x="44" y="40" width="32" height="40" rx="8" fill="#b9bfc6"/>
  <rect x="51" y="30" width="5" height="14" rx="2" fill="#8d959f"/><rect x="64" y="30" width="5" height="14" rx="2" fill="#8d959f"/>
  <path d="M60 80v14" stroke="#8d959f" stroke-width="4" stroke-linecap="round"/>
</g>`;
  return `<ellipse cx="60" cy="128" rx="34" ry="4" fill="#000" opacity=".18"/>${ringG(true)}${art}${ringG(false)}`;
};

